            "gridDisk returns E_MEMORY_ALLOC");
        t_assert(actualAllocCalls == 1, "gridDisk called alloc");
        t_assert(actualFreeCalls == 0, "gridDisk did not call free");

        for (int64_t i = 0; i < hexCount; i++) {
